// Cropin x MIT – Master v34, GEE round 3 (November QC polygons): the two exports round 2 did not deliver
// Generated by master_v34/07_make_gee_round3.py. Written by Claude, 2026-11-24.
//   v34_hansen.csv         Hansen loss years within 150 m (w1 task 4, unchanged)  -> nc_D_h_total_loss_px
//   v34_b6_monthly_qc.csv  Sentinel-2 B6 monthly medians, 3 years to the as-of year -> mm_B6_win
//     (round 2's B6 task came back with no B6 values. This version uses the Wave 2 monthly code that worked
//      in round 2, with band B6 added; the same cloud mask, months and medians as batch M1, so the same values.
//      Python keeps April–September only, as M1 did.)
// HOW TO RUN: paste into code.earthengine.google.com (project cropin-510901), click Run (Console prints
// "points __N__"), click RUN on both tasks, then download both CSVs from Drive folder "cropin_v34"
// into  Master Data/v34_work/gee/
// ============================================================================
var PTS = __PTS__;   // [lon, lat, label(-1), id, set, cutoff, season_start]
var allPts = ee.FeatureCollection(PTS.map(function(r) {
  return ee.Feature(ee.Geometry.Point([r[0], r[1]]), {label: r[2], id: r[3], set: r[4], cutoff: r[5], season_start: r[6]});
}));
print('points', allPts.size());
var FOLDER = 'cropin_v34';
var CUTOFFS = __CUTOFFS__;
function strip(fc) { return fc.map(function(f) { return ee.Feature(null, f.toDictionary()); }); }
function byCutoff(fn) {
  return ee.FeatureCollection(CUTOFFS.map(function(y) { return fn(allPts.filter(ee.Filter.eq('cutoff', y)), y); })).flatten();
}

// ---------- 1. Hansen loss years within 150 m (w1 task 4) ----------
var hansen = ee.Image('UMD/hansen/global_forest_change_2025_v1_13');
var lossyear = hansen.select('lossyear');
var hTable = lossyear.reduceRegions({collection: allPts.map(function(f) { return f.buffer(150); }),
    reducer: ee.Reducer.frequencyHistogram(), scale: 30, tileScale: 4})
  .map(function(f) { return ee.Feature(null, f.toDictionary()); });
var tc = hansen.select('treecover2000').reduceRegions({collection: allPts, reducer: ee.Reducer.first(), scale: 30})
  .map(function(f) { return ee.Feature(null, {id: f.get('id'), set: f.get('set'), treecover2000: f.get('first')}); });
Export.table.toDrive({collection: hTable.merge(tc), description: 'v34_hansen', folder: FOLDER, fileFormat: 'CSV'});
print('Hansen check (first 3 histograms)', hTable.limit(3));

// ---------- 2. Sentinel-2 monthly medians with B6 (w2 s2monthly code, bands B6 + B8) ----------
function win(y) { return [ee.Date.fromYMD(y - 2, 1, 1), ee.Date.fromYMD(y + 1, 1, 1)]; }
var CS = ee.ImageCollection('GOOGLE/CLOUD_SCORE_PLUS/V1/S2_HARMONIZED');
var S2B = ['B6', 'B8'];
function s2monthly(pts, y) {
  var reg = pts.geometry().bounds();
  return ee.FeatureCollection(ee.List.sequence(0, 35).map(function(i) {
    var start = win(y)[0].advance(i, 'month');
    var c = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED').filterBounds(reg)
      .filterDate(start, start.advance(1, 'month')).linkCollection(CS, ['cs'])
      .map(function(im) { return im.updateMask(im.select('cs').gte(0.6)); }).select(S2B);
    var empty = ee.Image.constant([0, 0, 0]).rename(S2B.concat(['n_clear'])).updateMask(0).toFloat();
    var img = ee.Image(ee.Algorithms.If(c.size().gt(0),
      c.median().addBands(c.select('B8').count().rename('n_clear')).toFloat(), empty));
    return strip(img.reduceRegions({collection: pts, reducer: ee.Reducer.first(), scale: 10, tileScale: 4}))
      .map(function(f) { return f.set('month', start.format('YYYY-MM')); });
  })).flatten();
}
var b6 = byCutoff(s2monthly);
print('B6 check (first 3 rows; B6 should be a number for most rows)', b6.limit(3));
Export.table.toDrive({collection: b6, description: 'v34_b6_monthly_qc', folder: FOLDER, fileFormat: 'CSV'});
